    const config: ScheduleCellConfig = {
      ...DEFAULT_SCHEDULE_CELL_CONFIG,
      participantDisplay: {
        ...DEFAULT_SCHEDULE_CELL_CONFIG.participantDisplay,
        showSeed: true
      }
    };
